#include <stdio.h>
#include <string.h>
#include <stdlib.h>

static void print_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) return;
    char buf[4096];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), f)) > 0) {
        fwrite(buf, 1, n, stdout);
    }
    fclose(f);
}

int main(int argc, char **argv) {
    if (argc == 1) {
        print_file("help.txt");
        return 0;
    }
    if (argc >= 2) {
        if (strcmp(argv[1], "--help") == 0 || strcmp(argv[1], "-h") == 0) {
            print_file("help.txt");
            return 0;
        }
        if (strcmp(argv[1], "--version") == 0) {
            printf("mlr 6.16.0\n");
            return 0;
        }
        if (strcmp(argv[1], "help") == 0) {
            if (argc >= 3) {
                if (strcmp(argv[2], "topics") == 0) {
                    print_file("topics.txt");
                    return 0;
                }
                if (strcmp(argv[2], "flags") == 0) {
                    print_file("flags.txt");
                    return 0;
                }
            }
            /* default for "mlr help" prints topics list */
            print_file("topics.txt");
            return 0;
        }
    }
    /* fallback: print same as no-verb */
    print_file("help.txt");
    return 0;
}
EOF

cat > compile.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail

# Compile the replica mlr frontend
gcc -O2 main.c -o executable
chmod +x executable

EOF

cat > .gitignore <<'EOF'
# Ignore built artifacts
executable
*.o
*.out
EOF

chmod +x compile.sh

# Add files to git
git add main.c compile.sh .gitignore help.txt topics.txt flags.txt || true
git commit -m "Reimplement minimal mlr help/version/topics/flags outputs" || true

# Build
./compile.sh

# Test outputs
printf "== no args ==\n"; ./executable | sed -n '1,120p'
printf "== --help ==\n"; ./executable --help | sed -n '1,120p'
printf "== --version ==\n"; ./executable --version
printf "== help topics ==\n"; ./executable help topics | sed -n '1,80p'
printf "== help flags (head) ==\n"; ./executable help flags | sed -n '1,40p'

EOF"}

